import { createTenant, useTemporaryDatabase } from "./_support/fixtures";
import type { Tenant } from "./_support/fixtures";

let cleanup: () => void;
/** Free plan: 3 seats, 2 projects. The fixture seeds four members. */
let free: Tenant;
let growth: Tenant;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  free = await createTenant("frugal", "free");
  growth = await createTenant("growing", "growth");
});

afterAll(() => {
  cleanup();
  rateLimitState.allowed = true;
});

describe("seat quota on invite", () => {
  it("rejects an invite once the plan's seats are taken", async () => {
    expect(getPlanLimits("free").seats).toBe(3);
    await expect(memberRepo.countActiveMembers(free.org.id)).resolves.toBe(4);

    await expect(
      invitationService.inviteMember(free.actors.owner, {
        orgId: free.org.id,
        email: "fifth@frugal.test",
        role: "member",
      }),
    ).rejects.toThrow(/seats/i);
  });

  it("writes no invitation row when the quota rejects the batch", async () => {
    await expect(
      invitationRepo.countPendingInvitations(free.org.id),
    ).resolves.toBe(0);
  });

  it("rejects a bulk invite as a whole rather than partially filling it", async () => {
    const limits = getPlanLimits("growth");
    expect(limits.seats).toBe(50);

    const invites = Array.from({ length: 49 }, (_, index) => ({
      email: `bulk-${index}@growing.test`,
      role: "member" as const,
    }));

    await expect(
      invitationService.inviteMembers(growth.actors.owner, {
        orgId: growth.org.id,
        invites,
      }),
    ).rejects.toThrow(/seats/i);

    await expect(
      invitationRepo.countPendingInvitations(growth.org.id),
    ).resolves.toBe(0);
  });

  it("counts a pending invitation against the seat quota", async () => {
    const before = await invitationRepo.countPendingInvitations(growth.org.id);

    await invitationService.inviteMember(growth.actors.owner, {
      orgId: growth.org.id,
      email: "solo@growing.test",
      role: "member",
    });

    await expect(
      invitationRepo.countPendingInvitations(growth.org.id),
    ).resolves.toBe(before + 1);
  });

  it("refuses the invite when the rate limiter says no", async () => {
    rateLimitState.allowed = false;

    await expect(
      invitationService.inviteMember(growth.actors.owner, {
        orgId: growth.org.id,
        email: "throttled@growing.test",
        role: "member",
      }),
    ).rejects.toThrow(/rate limit/i);

    rateLimitState.allowed = true;
  it("refuses an invite from an actor without member:invite", async () => {
    const tenant = await createTenant("invite-forbidden", "growth");

    await expect(
      invitationService.inviteMember(tenant.actors.member, {
        orgId: tenant.org.id,
        email: "newperson@invite-forbidden.test",
        role: "member",
      }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
  });

  // wouldExceedLimit(plan, "seats", seatsUsed) blocks the fourth seat on free.
  it("refuses an invite that would exceed the plan's seat quota", async () => {
    // The free plan tops out at 3 seats; createTenant already seeds 4 active
    // members (owner, admin, member, viewer), so the org starts over quota.
    const tenant = await createTenant("invite-seat-quota", "free");

    await expect(
      invitationService.inviteMember(tenant.actors.admin, {
        orgId: tenant.org.id,
        email: "onemore@invite-seat-quota.test",
        role: "member",
      }),
    ).rejects.toThrow(/seats/);
  });

  // A bulk invite checks the seat quota once, for the whole batch.
  it("checks the seat quota once for a bulk invite", async () => {
    const tenant = await createTenant("invite-bulk-quota", "starter");

    // Bring the org to 9 of its 10 starter seats: 4 from createTenant, 5 more
    // inserted directly so only a single seat remains.
    for (let i = 0; i < 5; i += 1) {
      const user = await userRepo.insertUser({
        email: `filler${i}@invite-bulk-quota.test`,
        name: `Filler ${i}`,
        passwordHash: "seed",
      });
      await memberRepo.insertMember(tenant.org.id, user.id, "member", null);
    }
    await expect(memberRepo.countActiveMembers(tenant.org.id)).resolves.toBe(9);

    // A batch of two exceeds the one remaining seat; the check runs once for
    // the whole batch, so nothing is created — not even the first invite.
    await expect(
      invitationService.inviteMembers(tenant.actors.admin, {
        orgId: tenant.org.id,
        invites: [
          { email: "batch-a@invite-bulk-quota.test", role: "member" },
          { email: "batch-b@invite-bulk-quota.test", role: "member" },
        ],
      }),
    ).rejects.toThrow(/seats/);

    await expect(
      invitationRepo.countPendingInvitations(tenant.org.id),
    ).resolves.toBe(0);

    // The same-sized single invite fits inside the one remaining seat.
    await expect(
      invitationService.inviteMembers(tenant.actors.admin, {
        orgId: tenant.org.id,
        invites: [{ email: "batch-c@invite-bulk-quota.test", role: "member" }],
      }),
    ).resolves.toHaveLength(1);
  });

  // consumeRateLimit(orgId, "member:invite") throttles invite bursts.
  it("rate-limits invites per organization", async () => {
    const tenant = await createTenant("invite-rate-limit", "growth");
  it("recounts the tenant's live rows", async () => {
    const result = await runUsageRollupJob(NOW);
    expect(result.processed).toBeGreaterThan(0);

    const usage = await usageRepo.getUsage(tenant.org.id);
    const live = await issueRepo.listIssues({
      orgId: tenant.org.id,
      limit: 100,
      cursor: null,
    });

    expect(usage.issuesUsed).toBe(live.total);
    expect(usage.seatsUsed).toBe(4);
  });
});

